
.form-card {
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  background: var(--c-surface, #fff);
  border: 2px solid var(--c-border, #ecd7e1);
  border-radius: 12px;
  padding: 18px 20px;
  font-family: var(--font-ui, sans-serif);
  color: var(--c-text, #4a3b45);
}

.form-title {
  margin: 0 0 4px;
  color: var(--c-primary, #e87ea4);
  font-size: 18px;
}

.form-sub {
  margin: 0 0 16px;
  font-size: 13px;
  color: var(--c-text-muted, #9a8a94);
}

.field {
  margin-bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.field label {
  font-size: 12px;
  font-weight: bold;
  color: var(--c-text, #4a3b45);
}

.field select {
  padding: 8px 10px;
  border: 1.5px solid var(--c-border, #ecd7e1);
  border-radius: 8px;
  background: var(--c-bg, #fdf7f2);
  font-size: 14px;
  color: var(--c-text, #4a3b45);
  font-family: var(--font-ui, sans-serif);
}

.submit {
  width: 100%;
  margin-top: 6px;
  padding: 10px;
  border: none;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--c-primary, #e87ea4), var(--c-accent, #d4a017));
  color: #fff;
  font-size: 15px;
  font-weight: bold;
  cursor: pointer;
  font-family: var(--font-ui, sans-serif);
}

.submit:disabled {
  opacity: 0.6;
  cursor: default;
}
